import z3,itertools,time,json
T=6; N=2*T; ALL=(1<<N)-1
masks=[];owners=[]
for mask in range(1,ALL+1):
 own=[i for i in range(T) if (mask>>(2*i))&3==3]
 if len(own)<=1:
  masks.append(mask); owners.append(own[0] if own else -1)
s=z3.Solver();s.set(timeout=100000)
x=[z3.Bool('x'+str(m)) for m in masks]
for v in range(N):
 inds=[q for q,m in enumerate(masks) if m>>v&1 and owners[q]!=v//2]
 s.add(z3.PbLe([(x[q],1) for q in inds],2))
for a,b in itertools.combinations(range(N),2):
 s.add(z3.Or([x[q] for q,m in enumerate(masks) if m>>a&1 and m>>b&1]))
# Every own-class column allowed for free.
for i in range(T):s.add(x[masks.index(3<<(2*i))])
start=time.time()
for it in range(2000):
 res=s.check()
 if res!=z3.sat:
  print('RESULT',res,'iterations',it,'time',time.time()-start,flush=True); break
 model=s.model(); selected=[q for q in range(len(x)) if z3.is_true(model[x[q]])]
 cover=None
 for sz in range(1,T):
  for comb in itertools.combinations(selected,sz):
   union=0
   for q in comb:union|=masks[q]
   if union==ALL:cover=comb;break
  if cover:break
 if cover is None:
  print('FOUND',[(masks[q],owners[q]) for q in selected],flush=True);break
 s.add(z3.Or([z3.Not(x[q]) for q in cover]))
 if it%10==0:print(it,'sel',len(selected),'cover',len(cover),'time',time.time()-start,flush=True)

